<script setup lang="ts">import type{RecruitmentSeason}from'@career-launch/shared';import{onMounted,ref}from'vue';import{repository}from'../../services/repository';const items=ref<RecruitmentSeason[]>([]);async function load(){items.value=await repository.admin.seasons.list()}async function toggle(item:RecruitmentSeason){await repository.admin.seasons.save({...item,active:!item.active});await load()}onMounted(load)</script>
<template><section><header class="admin-page-head"><div><h1>招聘批次</h1><p>统一配置秋招、春招、提前批与补录的展示周期。</p></div><button class="cl-primary-button">新增批次</button></header><div class="admin-table-wrap"><table class="admin-table"><thead><tr><th>批次名称</th><th>年份</th><th>类型</th><th>开始时间</th><th>结束时间</th><th>状态</th><th>操作</th></tr></thead><tbody><tr v-for="item in items" :key="item.id"><td><strong>{{item.name}}</strong></td><td>{{item.year}}</td><td>{{item.type}}</td><td>{{new Date(item.startsAt).toLocaleDateString('zh-CN')}}</td><td>{{new Date(item.endsAt).toLocaleDateString('zh-CN')}}</td><td>{{item.active?'展示中':'未启用'}}</td><td><button class="admin-link-button" @click="toggle(item)">{{item.active?'停用':'启用'}}</button></td></tr></tbody></table></div></section></template>
